function writeHoursMessage() {
  let sheet = SpreadsheetApp.getActiveSheet()
  let nameCell = sheet.getRange("A2")
  let firstName = nameCell.getValue()
  let hoursCell = sheet.getRange("E2")
  let hours = Number(hoursCell.getValue())
  let message = `${firstName} has ${hours} volunteer hours.`
  let messageCell = sheet.getRange("G2")
  messageCell.setValue(message)
}
